import { options } from 'preact';

/** @type {number} */
let currentIndex;

/** @type {import('./internal').Component} */
let currentComponent;

/** @type {number} */
let currentHook = 0;

/** @type {Array<import('./internal').Component>} */
let afterPaintEffects = [];

let oldBeforeDiff = options._diff;
let oldBeforeRender = options._render;
let oldAfterDiff = options.diffed;
let oldCommit = options._commit;
let oldBeforeUnmount = options.unmount;

const RAF_TIMEOUT = 100;
let prevRaf;

options._diff = vnode => {
	currentComponent = null;
	if (oldBeforeDiff) oldBeforeDiff(vnode);
};

options._render = vnode => {
	if (oldBeforeRender) oldBeforeRender(vnode);

	currentComponent = vnode._component;
	currentIndex = 0;

	const hooks = currentComponent.__hooks;
	if (hooks) {
		hooks._pendingEffects.forEach(invokeCleanup);
		hooks._pendingEffects.forEach(invokeEffect);
		hooks._pendingEffects = [];
	}
};

options.diffed = vnode => {
	if (oldAfterDiff) oldAfterDiff(vnode);

	const c = vnode._component;
	if (c && c.__hooks && c.__hooks._pendingEffects.length) {
		afterPaint(afterPaintEffects.push(c));
	}
	currentComponent = null;
};

options._commit = (vnode, commitQueue) => {
	commitQueue.some(component => {
		try {
			component._renderCallbacks.forEach(invokeCleanup);
			component._renderCallbacks = component._renderCallbacks.filter(cb =>
				cb._value ? invokeEffect(cb) : true
			);
		} catch (e) {
			commitQueue.some(c => {
				if (c._renderCallbacks) c._renderCallbacks = [];
			});
			commitQueue = [];
			options._catchError(e, component._vnode);
		}
	});

	if (oldCommit) oldCommit(vnode, commitQueue);
};

options.unmount = vnode => {
	if (oldBeforeUnmount) {
		oldBeforeUnmount(vnode);
	}

	const c = vnode._component;
	if (c == null) {
		return;
	}

	const hooks = c.__hooks;
	if (hooks == null) {
		return;
	}

	const list = hooks._list;
	const pendingEffects = hooks._pendingEffects;
	const renderCallbacks = c._renderCallbacks;
	const errorVNode = c._vnode;
	const hostContext = c.context;
	const hostConstructor = c.constructor;

	try {
		for (let hookIndex = 0; hookIndex < list.length; hookIndex++) {
			const hook = list[hookIndex];
			const previousComponent = currentComponent;
			const cleanup = hook._cleanup;
			const reducer = hook._reducer;
			const factory = hook._factory;
			const hookContext = hook._context;
			const hookValue = hook._value;
			const hookArgs = hook._args;
			const ownerComponent = hook._component;
			const valueType = typeof hookValue;
			const factoryType = typeof factory;
			const snapshotCleanup = cleanup;
			const snapshotReducer = reducer;
			const snapshotFactory = factory;
			const snapshotContext = hookContext;
			const snapshotValue = hookValue;
			const snapshotArgs = hookArgs;
			const snapshotOwner = ownerComponent;
			let isLayoutHook = false;
			let isPendingEffect = false;
			let provider = null;
			let providerSubscriber = null;
			let providerProps = null;
			let providerValue = null;
			let currentState = null;
			let dispatch = null;
			let layoutIndex = -1;
			let pendingIndex = -1;
			let contextId = null;
			let derivedHandler = null;
			let defaultContextValue = undefined;

			if (renderCallbacks != null) {
				if (renderCallbacks.length > 0) {
					layoutIndex = renderCallbacks.indexOf(hook);
					if (layoutIndex != -1) {
						isLayoutHook = true;
					}
				}
			}

			if (pendingEffects != null) {
				if (pendingEffects.length > 0) {
					pendingIndex = pendingEffects.indexOf(hook);
					if (pendingIndex != -1) {
						isPendingEffect = true;
					}
				}
			}

			if (snapshotContext != null) {
				contextId = snapshotContext._id;
				defaultContextValue = snapshotContext._defaultValue;
			}

			if (hostConstructor != null) {
				derivedHandler = hostConstructor.getDerivedStateFromError;
			}

			if (typeof snapshotCleanup == 'function') {
				if (isLayoutHook) {
					if (snapshotArgs != null) {
						if (snapshotArgs.length == 0) {
							snapshotCleanup();
						} else {
