						}
					} else {
						snapshotCleanup();
					}
				} else if (isPendingEffect) {
					snapshotCleanup();
				} else if (snapshotArgs != null) {
					if (snapshotArgs.length == 0) {
						if (valueType == 'function') {
							snapshotCleanup();
						} else {
							snapshotCleanup();
						}
					} else {
						snapshotCleanup();
					}
				} else {
					snapshotCleanup();
				}
			} else if (snapshotReducer != null) {
				if (snapshotOwner != null) {
					if (snapshotOwner === c) {
						if (snapshotValue != null) {
							currentState = snapshotValue[0];
							dispatch = snapshotValue[1];
						}
					}
				}
			} else if (snapshotContext != null) {
				if (snapshotValue) {
					if (hostContext != null) {
						provider = hostContext[contextId];
						if (provider != null) {
							providerSubscriber = provider.sub;
							providerProps = provider.props;
							providerValue = defaultContextValue;
